contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address account) public payable {
        require(account != address(0));

        // c is freshly deployed and uninitialized: controller() is unset,
        // so settle() cannot possibly complete successfully.
        bool reverted;
        try c.settle() { reverted = false; } catch { reverted = true; }

        // State must be unchanged and readable afterwards.
        Position memory p = c.position(account);
        uint256 lv = c.latestVersion();
        uint256 accountLv = c.latestVersion(account);

        assert(
            reverted &&
            UFixed18.unwrap(p.maker) == 0 &&
            UFixed18.unwrap(p.taker) == 0 &&
            lv == 0 &&
            accountLv == 0
        );
    }

    receive() external payable {}
}

