contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bool newClosed, uint256 salt) public {
        require(true, "");
        salt;

        // Read-only pre-state observations (allowed inside expressions)
        uint256 vBefore = c.latestVersion();

        bool reverted;
        try c.updateClosed(newClosed) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The caller of c is this test contract, which is not the coordinator
        // owner of the product (the controller storage is unset), so the
        // onlyProductOwner modifier must make every updateClosed call revert,
        // regardless of the requested flag, and the product's latest version
