    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address account) public {
        // The caller of every call on c is this test contract (msg.sender),
        // which is neither the account nor the coordinator owner (unset -> zero).
        require(account != address(this), "account must differ from caller");
        require(account != address(0), "account must not be zero");

        Position memory before = c.position(account);

        bool reverted;
        try c.closeMakeFor(account, 0) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // onlyOwnerOrAccount must make the call revert, and the failed call
        // must not change the account's position.
        Position memory afterP = c.position(account);
        assert(reverted && afterP.maker.unwrap() == before.maker.unwrap() && afterP.taker.unwrap() == before.taker.unwrap());
    }

    receive() external payable {}
}

