contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public {
        // On a fresh deployment the controller address is unset, so every call
        // that touches controller-dependent state must revert.
        bool settleReverted;
        try c.settle() { settleReverted = false; } catch { settleReverted = true; }

        bool updateReverted;
        try c.updateMaintenance(UFixed18.wrap(amount)) { updateReverted = false; } catch { updateReverted = true; }

        // The attempted maintenance update must not have taken effect.
        uint256 maintenanceAfter = UFixed18.unwrap(c.maintenance());

        assert(
            settleReverted &&
            updateReverted &&
            maintenanceAfter == 0
        );
    }

    receive() external payable {}
}

