contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address account) public {
        require(true);

        bool closedFlag = c.closed();
        bool liq = c.isLiquidating(account);
        bool acctClosed = c.isClosed(account);

        Position memory pos = c.position(account);
        PrePosition memory pre = c.pre(account);

        UFixed18 maint = c.maintenance(account);
        UFixed18 maintNext = c.maintenanceNext(account);

        uint256 acctVer = c.latestVersion(account);
        uint256 globVer = c.latestVersion();

        Position memory globPos = c.positionAtVersion(globVer);

        assert(
            !closedFlag &&
            !liq &&
            !acctClosed &&
            UFixed18.unwrap(pos.maker) == 0 &&
            UFixed18.unwrap(pos.taker) == 0 &&
            pre.oracleVersion == 0 &&
            UFixed18.unwrap(pre.openPosition.maker) == 0 &&
            UFixed18.unwrap(pre.openPosition.taker) == 0 &&
            UFixed18.unwrap(pre.closePosition.maker) == 0 &&
            UFixed18.unwrap(pre.closePosition.taker) == 0 &&
            UFixed18.unwrap(maint) == 0 &&
            UFixed18.unwrap(maintNext) == 0 &&
            acctVer == 0 &&
            globVer == 0 &&
            UFixed18.unwrap(globPos.maker) == 0 &&
            UFixed18.unwrap(globPos.taker) == 0
        );
    }

    receive() external payable {}
}

